        fs::write(&full_path, "# a\n\n## 0.2.0\n\n- first\n").unwrap();

        prepend(root, changelog_path, "cargo/a", "## 0.3.0\n\n- second\n", &permit()).unwrap();

        let result = fs::read_to_string(&full_path).unwrap();
        assert_eq!(
            result.matches("\n# ").count() + usize::from(result.starts_with("# ")),
            1,
            "{result}"
        );
        assert!(result.starts_with("# cargo/a\n\n## 0.3.0"), "{result}");
        assert!(result.contains("## 0.2.0"), "old entry lost:\n{result}");
    }

    #[test]
    fn prepend_is_idempotent_for_same_version() {
        // If the existing changelog already contains the version heading being
        // inserted, prepend() should return the existing content unchanged
        // rather than duplicating the section.
        let workspace = tempfile::tempdir().unwrap();
        let root = workspace.path();
        let changelog_path = std::path::Path::new("CHANGELOG.md");
        let full_path = root.join(changelog_path);

        let existing = "# my-pkg\n\n## 1.0.0\n\nSome content\n";
        fs::write(&full_path, existing).unwrap();

        prepend(root, changelog_path, "my-pkg", "## 1.0.0\n\nNew content\n", &permit())
            .expect("prepend should succeed");

        let result = fs::read_to_string(&full_path).unwrap();

        let occurrences = result.matches("## 1.0.0").count();
        assert_eq!(
            occurrences, 1,
            "## 1.0.0 should appear exactly once, got {occurrences} times in:\n{result}"
        );
        assert!(
            result.contains("Some content"),
            "existing content should be preserved — got:\n{result}"
        );
    }

    #[test]
    fn test_prepend_stable_after_prerelease_not_suppressed() {
        // CORR-001: "## 1.0.0" must not be suppressed by the idempotency guard
        // when the file already contains "## 1.0.0-alpha.1", because the stable
        // version string is a substring of the pre-release heading.
        let workspace = tempfile::tempdir().unwrap();
        let root = workspace.path();
        let changelog_path = std::path::Path::new("CHANGELOG.md");
        let full_path = root.join(changelog_path);

        let existing = "## 1.0.0-alpha.1\n\n- alpha change\n";
        fs::write(&full_path, existing).unwrap();

        prepend(
            root,
            changelog_path,
            "my-pkg",
            "## 1.0.0\n\n### Patch Changes\n\n- Stable release\n",
            &permit(),
        )
        .expect("prepend should succeed");

        let result = fs::read_to_string(&full_path).unwrap();

        // The stable heading must appear as a standalone line, not just as
        // a substring match that could fire on "## 1.0.0-alpha.1".
        assert!(
            result.lines().any(|l| l.trim() == "## 1.0.0"),
            "stable heading '## 1.0.0' must appear as its own line; got:\n{result}"
        );
        // The pre-release heading must still be present.
        assert!(
            result.contains("## 1.0.0-alpha.1"),
            "pre-release heading must still be present; got:\n{result}"
        );
    }

    #[test]
    fn prepend_creates_nested_grandparent_and_parent_dirs_via_shared_atomic_write() {
        let workspace = tempfile::tempdir().unwrap();
        let root = workspace.path();

        // Neither "packages" (grandparent) nor "packages/my-pkg" (parent) exist yet.
        let changelog_path = std::path::Path::new("packages/my-pkg/CHANGELOG.md");
        assert!(!root.join("packages").exists());

        prepend(
            root,
            changelog_path,
            "my-pkg",
            "### Patch Changes\n\n- Fix bug",
            &permit(),
        )
        .expect("prepend should create nested dirs and write durably");

        let full_path = root.join(changelog_path);
        assert!(full_path.exists());
        let contents = fs::read_to_string(&full_path).unwrap();
        assert!(contents.starts_with("# my-pkg\n\n"));
        assert!(contents.contains("- Fix bug"));

        // No leftover temp files from the shared NamedTempFile-based atomic_write.
        let parent_entries: Vec<_> = fs::read_dir(full_path.parent().unwrap())
            .unwrap()
            .map(|e| e.unwrap().file_name())
            .collect();
        assert_eq!(parent_entries, vec![std::ffi::OsString::from("CHANGELOG.md")]);
    }

    const GROUPED_NEW: &str = "## 1.2.0\n\n_2026-11-08 · [compare](https://github.com/o/r/compare/a...b)_\n\n### Major Changes\n\n- Break it.\n\n### Patch Changes\n\n- Fix it.\n";
    const FLAT_OLD: &str = "## 1.1.0\n\n- Old flat entry.\n\n## 1.0.0\n\n- First.\n";

    fn read_after_prepend(existing: Option<&str>, rendered: &str) -> String {
        let workspace = tempfile::tempdir().unwrap();
        let root = workspace.path();
        let path = std::path::Path::new("CHANGELOG.md");
        if let Some(existing) = existing {
            fs::write(root.join(path), existing).unwrap();
        }
        prepend(root, path, "my-pkg", rendered, &permit()).unwrap();
        fs::read_to_string(root.join(path)).unwrap()
    }

    #[test]
    fn prepend_puts_a_grouped_section_above_an_existing_flat_changelog() {
        let result = read_after_prepend(Some(&format!("# my-pkg\n\n{FLAT_OLD}")), GROUPED_NEW);
        assert_eq!(result, format!("# my-pkg\n\n{GROUPED_NEW}\n{FLAT_OLD}"));
    }

    #[test]
    fn prepend_puts_a_flat_section_above_an_existing_grouped_changelog() {
        let flat_new = "## 1.3.0\n\n- Flat again.\n";
        let result = read_after_prepend(Some(&format!("# my-pkg\n\n{GROUPED_NEW}")), flat_new);
        assert_eq!(result, format!("# my-pkg\n\n{flat_new}\n{GROUPED_NEW}"));
    }

    /// A rerun of an already-written version is skipped in both layouts; the `###` lines are never mistaken for it.
    #[test]
    fn prepend_skips_a_version_already_present_in_either_layout() {
        let grouped = format!("# my-pkg\n\n{GROUPED_NEW}\n{FLAT_OLD}");
        assert_eq!(read_after_prepend(Some(&grouped), GROUPED_NEW), grouped);
        let dup_of_flat = "## 1.1.0\n\n_2026-11-08_\n\n### Patch Changes\n\n- Again.\n";
        assert_eq!(read_after_prepend(Some(&grouped), dup_of_flat), grouped);
    }

    #[test]
    fn prepend_creates_a_changelog_from_a_grouped_section() {
        let result = read_after_prepend(None, GROUPED_NEW);
        assert_eq!(result, format!("# my-pkg\n\n{GROUPED_NEW}\n"));
    }

    #[test]
    fn find_section_returns_a_whole_grouped_section_and_stops_at_the_next_version() {
        let changelog = format!("# my-pkg\n\n{GROUPED_NEW}\n{FLAT_OLD}");
        let v = |s: &str| Version::parse(s, VersionGrammar::SemVer).unwrap();
        let section = find_section(&changelog, &v("1.2.0")).unwrap();
        assert_eq!(section, GROUPED_NEW.strip_prefix("## 1.2.0\n\n").unwrap().trim());
        assert!(section.starts_with("_2026-11-08"));
        assert!(section.contains("### Major Changes") && section.contains("### Patch Changes"));
        assert_eq!(extract_section(&changelog, &v("1.2.0")), Some(section));
        assert_eq!(find_section(&changelog, &v("1.1.0")), Some("- Old flat entry."));
    }
